\begin{tikzpicture}\begin{axis}[width=6cm,height=5.5cm,axis lines=middle,axis line style={-{Stealth}},xmin=-4,xmax=4,ymin=-6,ymax=4,xtick={-4,-3,...,4},ytick={-6,-4,...,4},grid=both,clip=false,scaled ticks=false,ticklabel style={font=\small,/pgf/number format/fixed},xlabel={$x$},ylabel={$y$}]
